const rows = $input.all();

let lastTopic = '';
let lastTime = '';
let lastTrainer = '';

const result = [];

for (const item of rows) {
  const r = item.json;

  const currentTopic = (r.Topic || '').trim();
  const dateFormat = (r['Date and format'] || '').trim();
  const currentTime = (r.Time || '').trim();
  const currentTrainer = (r.Trainer || '').trim();

  // --------------------------------
  // TIME
  // --------------------------------

  if (currentTime) {
    const timeMatch = currentTime.match(/(\d{1,2}:\d{2})/);

    if (timeMatch) {
      lastTime = timeMatch[1];
    }

    // Mentor sessions have no fixed time
    if (
      currentTime
        .toLowerCase()
        .includes('scheduled by the mentor')
    ) {
      lastTime = '';
    }
  }

  // --------------------------------
  // TRAINER
  // --------------------------------

  if (currentTrainer) {
    lastTrainer = currentTrainer;
  }

  // --------------------------------
  // SKIP MODULE HEADERS
  // --------------------------------

  if (
    currentTopic === 'JavaScript Module' ||
    currentTopic === 'AT_JS Module'
  ) {
    continue;
  }

  // --------------------------------
  // TOPIC IS ACTUALLY A DATE
  // Example:
  // 21.10.2026 (Group Interview)
  // --------------------------------

  const topicIsDate = currentTopic.match(
    /^\d{2}\.\d{2}\.\d{4}\s*\([^)]+\)$/
  );

  if (topicIsDate) {
    result.push({
      json: {
        Topic: lastTopic,
        'Date and format': currentTopic,
        Time: lastTime,
        Trainer: lastTrainer
      }
    });

    continue;
  }

  // --------------------------------
  // NEW TOPIC
  // --------------------------------

  if (currentTopic) {
    lastTopic = currentTopic;
  }

  // No date → nothing to add
  if (!dateFormat) {
    continue;
  }

  // --------------------------------
  // MULTIPLE DATES IN ONE CELL
  //
  // Example:
  // 10.12.2026 (Q&A) 15.12.2026 (Group Interview)
  // --------------------------------

  const multipleDates = [
    ...dateFormat.matchAll(
      /\d{2}\.\d{2}\.\d{4}\s*\([^)]+\)/g
    )
  ];

  if (multipleDates.length > 1) {
    for (const match of multipleDates) {
      result.push({
        json: {
          Topic: lastTopic,
          'Date and format': match[0],
          Time: lastTime,
          Trainer: lastTrainer
        }
      });
    }

    continue;
  }

  // --------------------------------
  // DATE RANGE WITHOUT FIXED TIME
  //
  // Examples:
  // 02-03.11.2026
  // 03-09.11.2026
  //
  // IMPORTANT:
  // Time must be EMPTY.
  // --------------------------------

  const simpleDateRange = dateFormat.match(
    /^\d{2}\s*-\s*\d{2}\.\d{2}\.\d{4}/
  );

  if (simpleDateRange) {
    result.push({
      json: {
        Topic: lastTopic,
        'Date and format': dateFormat,
        Time: '',
        Trainer: lastTrainer
      }
    });

    continue;
  }

  // --------------------------------
  // DATE RANGE
  //
  // Examples:
  // 03.11.- 06.11.2026
  // 09.11.- 13.11.2026
  // 16.11.- 20.11.2026
  // 30.11.- 04.12.2026
  //
  // These also have NO fixed time.
  // --------------------------------

  const dateRange = dateFormat.match(
    /^\d{2}\.\d{2}\.\s*-\s*\d{2}\.\d{2}\.\d{4}\s*\([^)]+\)$/
  );

  if (dateRange) {
    result.push({
      json: {
        Topic: lastTopic,
        'Date and format': dateRange[0],
        Time: '',
        Trainer: lastTrainer
      }
    });

    continue;
  }

  // --------------------------------
  // NORMAL DATE
  // --------------------------------

  result.push({
    json: {
      Topic: lastTopic,
      'Date and format': dateFormat,
      Time: lastTime,
      Trainer: lastTrainer
    }
  });
}

return result;

const items = $input.all();
const result = [];

function nextDay(date) {
  const [y, m, d] = date.split('-').map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d + 1));
  return dt.toISOString().slice(0, 10);
}

function daysBetween(start, end) {
  const days = [];
  for (let d = start; d <= end; d = nextDay(d)) days.push(d);
  return days;
}

for (const { json } of items) {
  const topic = json.Topic;
  const dateText = (json['Date and format'] || '').trim();
  const time = (json.Time || '').trim();

  const format = (dateText.match(/\(([^)]+)\)/) || [])[1];
  const summary = format ? `${topic} (${format})` : topic;

  // Діапазон: "03.11.- 06.11.2026" або "02-03.11.2026"
  let m = dateText.match(/^(\d{2})\.(\d{2})\.\s*-\s*(\d{2})\.(\d{2})\.(\d{4})/);
  let first, last;

  if (m) {
    first = `${m[5]}-${m[2]}-${m[1]}`;
    last = `${m[5]}-${m[4]}-${m[3]}`;
  } else if ((m = dateText.match(/^(\d{2})\s*-\s*(\d{2})\.(\d{2})\.(\d{4})/))) {
    first = `${m[4]}-${m[3]}-${m[1]}`;
    last = `${m[4]}-${m[3]}-${m[2]}`;
  }

  if (first) {
    for (const day of daysBetween(first, last)) {
      result.push({ json: { summary, start: day, end: nextDay(day), allDay: true } });
    }
    continue;
  }

  // Одна дата
  const d = dateText.match(/(\d{2})\.(\d{2})\.(\d{4})/);
  if (!d) throw new Error(`Cannot recognize date: ${dateText}`);
  const date = `${d[3]}-${d[2]}-${d[1]}`;

  if (time) {
    const [h, min] = time.split(':').map(Number);
    const pad = n => String(n).padStart(2, '0');
    const endDate = h + 1 >= 24 ? nextDay(date) : date;
    result.push({
      json: {
        summary,
        start: `${date}T${time}:00`,
        end: `${endDate}T${pad((h + 1) % 24)}:${pad(min)}:00`,
        allDay: false
      }
    });
  } else {
    result.push({ json: { summary, start: date, end: nextDay(date), allDay: true } });
  }
}

return result;

const existing = $('Get many events').all().map(i => {
  const s = i.json.start || {};
  return `${i.json.summary}|${(s.date || s.dateTime || '').slice(0, 10)}`;
});

return $('Prepare Calendar Event').all().filter(i => {
  const key = `${i.json.summary}|${i.json.start.slice(0, 10)}`;
  return !existing.includes(key);
});
